INFOPLIST = {
    "en": "Nod reads head motion from your AirPods to recognize when you nod, shake your head or step away.",
    "fr": "Nod lit les mouvements de la tête de vos AirPods pour reconnaître quand vous hochez, secouez la tête ou vous éloignez.",
    "es": "Nod lee el movimiento de la cabeza de tus AirPods para reconocer cuándo asientes, niegas o te alejas.",
    "it": "Nod legge il movimento della testa dalle AirPods per riconoscere quando annuisci, scuoti la testa o ti allontani.",
}
APPLE_EVENTS = {
    "en": "Nod opens Terminal to run the update command when you ask it to.",
    "fr": "Nod ouvre Terminal pour exécuter la commande de mise à jour quand vous le demandez.",
    "es": "Nod abre Terminal para ejecutar el comando de actualización cuando se lo pides.",
    "it": "Nod apre il Terminale per eseguire il comando di aggiornamento quando glielo chiedi.",
}

REMINDERS = {
    "en": "Nod creates Watch alerts in the \\\"Nod\\\" Reminders list and deletes them after you answer.",
    "fr": "Nod crée les alertes pour la Watch dans la liste \\\"Nod\\\" de Rappels et les supprime après votre réponse.",
    "es": "Nod crea los avisos para el Watch en la lista \\\"Nod\\\" de Recordatorios y los borra después de tu respuesta.",
    "it": "Nod crea nella lista \\\"Nod\\\" di Promemoria gli avvisi per il Watch e li cancella dopo la tua risposta.",
}

if __name__ == "__main__":
    root = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "Localization")
    for i, lang in enumerate(["en", "fr", "es"]):
        d = os.path.join(root, f"{lang}.lproj")
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, "Localizable.strings"), "w", encoding="utf-8") as f:
            f.write(f"/* Nod: {lang}. Generato da tools/translations.py: modifica lì. */\n\n")
            for key in sorted(T):
                f.write(f'"{key}" = "{T[key][i]}";\n')
    os.makedirs(os.path.join(root, "it.lproj"), exist_ok=True)
    with open(os.path.join(root, "it.lproj", "Localizable.strings"), "w", encoding="utf-8") as f:
        f.write("/* Nod: italiano. Vuoto di proposito: la chiave di ogni testo è già l'italiano (Sources/Localization.swift). */\n")
    for lang in ["en", "fr", "es", "it"]:
        with open(os.path.join(root, f"{lang}.lproj", "InfoPlist.strings"), "w", encoding="utf-8") as f:
            f.write(f'"NSMotionUsageDescription" = "{INFOPLIST[lang]}";\n')
            f.write(f'"NSAppleEventsUsageDescription" = "{APPLE_EVENTS[lang]}";\n')
            f.write(f'"NSRemindersFullAccessUsageDescription" = "{REMINDERS[lang]}";\n')
            f.write(f'"NSRemindersUsageDescription" = "{REMINDERS[lang]}";\n')
    print(f"{len(T)} voci scritte")
